fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut lo: usize = 0;
    // Safe because v is non-empty
    let mut hi: usize = v.len() - 1;

    while lo <= hi {
        // Avoid potential overflow
        let mid = lo + (hi - lo) / 2;
        let val = v[mid];

        if val < k {
            lo = mid + 1;
        } else if val > k {
            // Since k is guaranteed to be in v, mid > 0 here unless k == v[0] and mid == 0,
            // but in that case val == k and we'd have returned already.
            hi = mid - 1;
        } else {
            return mid;
        }
    }

    // Given the precondition that k is in v, we should never reach here.
    unreachable!("Target value must exist in the array")
}

